export type SectionTypeKey =
  | 'bedroom'
  | 'bathroom'
  | 'oht'
  | 'sump'
  | 'apartment'
  | 'column-bit'
  | 'floor-shell'
  | 'staircase'
  | 'lift'
  | 'ots'
  | 'roof'
  | 'beam-bit'
  | 'slab';

export type Option = {
  label: string;
  value: string;
};

export type SectionModelRow = {
  id: string;
  [key: string]: any;
};

export type CellRenderer = (
  row: SectionModelRow,
  rowIndex: number,
  updateCell: (key: string, value: any) => void,
  disabled: boolean,
  deleteRow: (rowIndex: number) => void,
  rows: SectionModelRow[]
) => React.ReactNode;

export type GridColumn = {
  key: string;
  header: string;
  width: string;
  align?: 'left' | 'center' | 'right';
  renderCell: CellRenderer;
};

export type GridChildSection = {
  id: string;
  title: string;
  titleRenderer?: (sectionName: string) => React.ReactNode;
  columns: GridColumn[];
  initialRows: Omit<SectionModelRow, 'id'>[];
  createRow: () => Omit<SectionModelRow, 'id'>;
  addLabel?: string;
  allowAdd?: boolean;
  tableWidth?: string;
  entityGroups?: EntityGroupConfig[];
};

export type EntityGroupConfig = {
  entity: string;
  parameterColumns: GridColumn[];
  parameterPairs?: { value: GridColumn; uom: GridColumn }[];
  fixedColumns?: GridColumn[];
  showActions?: boolean;
};

export type GridSectionConfig = {
  id: string;
  title: string;
  titleRenderer?: (sectionName: string) => React.ReactNode;
  columns: GridColumn[];
  initialRows: Omit<SectionModelRow, 'id'>[];
  createRow: () => Omit<SectionModelRow, 'id'>;
  addLabel?: string;
  allowAdd?: boolean;
  children?: GridChildSection[];
  showHeaderAdd?: boolean;
  hideMainTable?: boolean;
  hideTableTitle?: boolean;
  tableWidth?: string;
  rowSpanKeys?: string[];
  entityGroups?: EntityGroupConfig[];
  procedureGroups?: {
    category: string;
    procedures: {
      name: string;
      workCategory?: string;
      portions: { portionType: string; portionName: string; measurement: string; quantity: string; uom: string }[];
      tasks: { workName: string; taskName: string; itemSetName: string; measurement: string; quantity: string; uom: string }[];
      itemSets?: { itemSetType: string; itemSetName: string; measurement: string; quantity: string; uom: string }[];
      services?: { serviceName: string; measurement: string; quantity: string; uom: string }[];
    }[];
  }[];
};

export type SectionConfig = {
  label: string;
  value: SectionTypeKey;
  defaultScope: string;
  defaultMeasurementType?: string;
  tabs: GridSectionConfig[];
};

