export const buildBlankSectionRows = (section: GridSectionConfig): SectionModelRow[] =>
  section.initialRows.map((row, index) => ({ id: createId(section.id, index), ...row }));

export const getSectionLabel = (value: SectionTypeKey) => SECTION_CONFIGS[value].label;

export const renderSectionTitle = (section: GridSectionConfig, sectionName: string) =>
  section.titleRenderer ? section.titleRenderer(sectionName) : section.title;

export const APARTMENT_CHILD_LABELS: Record<string, string> = APARTMENT_CHILD_SECTIONS.reduce(
  (acc, child) => ({ ...acc, [child.key]: child.label }),
  {} as Record<string, string>,
);
