// Only explicit section-to-portion mappings belong in the navigator.
export const getMappedPortionTypes = (sectionKey: string): string[] => {
  const mappedBySection: Record<string, string[]> = {
    'stair-room': ['lintel-bit', 'sun-shade', 'staircase-slab'],
    'head-room': ['lintel-bit', 'sun-shade', 'column-portion', 'beam-bit', 'slab'],
    'lift-room': ['lintel-bit', 'column-portion', 'beam-bit', 'slab'],
    'machine-room': ['lintel-bit', 'column-portion', 'beam-bit', 'slab'],
  };
  if (mappedBySection[sectionKey]) return mappedBySection[sectionKey];
  const portions = sectionKey === 'floor-structure' ? floorStructurePortions
    : sectionKey === 'apartment' ? apartmentPortions : [];
  return Array.from(new Set(portions.map(portion => portion.portionType === 'column-bit' ? 'column-portion' : portion.portionType)));
};

