export type LayoutRow = { name: string; measurement: string; quantity: string; uom: string; itemSetType?: string; sequence?: number };
export type LayoutProcedure = { name: string; tables: Record<string, LayoutRow[]> };

// Procedure names copied from Section Model 7; maintained independently here.
const procedureNames: Record<string, string[]> = {
  'floor-structure': ['Column Extension Work', 'Staircase Slab Extension Work', 'Roof Work', 'Roof Pipe Work'],
  apartment: ['Partition Work', 'Lintel Work', 'Inner Plastering Work', 'Kitchen Counter Work', 'Cup Board Work', 'Electrical Wall Pipe Work', 'Wiring Work', 'Switch Work', 'Tile Work', 'Inner Painting Work', 'UPVC Work', 'Grill Work', 'Door Frame Work', 'Door Work', 'Concealed Work', 'Fittings Work'],
};

export type LayoutModel = {
  key: number;
  name: string;
  section_type: string;
  description: string;
  scope: string;
  procedures: LayoutProcedure[];
};

// Independent snapshot of Section Model 7 procedure data with the existing model catalog.
const templateAliases: Record<string, string> = {
  headroom: 'staircase', staircaseroom: 'staircase',
  liftfooting: 'lift', liftroom: 'lift', machineroom: 'lift',
  'sump-wall': 'sump', 'sump-roof': 'sump', 'sump-floor': 'sump',
  'task-floor': 'oht', 'tank-roof': 'oht', 'tank-wall': 'oht', 'tank-columns': 'oht',
  otsfloor: 'ots', diningroom: 'living-dining', livingroom: 'living-dining', 'sun-shade': 'staircase',
};

// Adapt the existing local section templates without inventing quantities or item sets.
const templateProcedures = (sectionType: string): LayoutProcedure[] => {
  const config = PORTION_CONFIGS[templateAliases[sectionType] || sectionType];
  if (!config) return [];
  const tables = config.tabs.flatMap((tab: any) => [tab, ...(tab.children || [])]);
  const measurementRows = tables.filter((table: any) => table.id.includes('property-input') || table.id.includes('measurement') || table.id.includes('metrics'))
    .flatMap((table: any) => table.initialRows || []).filter((row: any) => row.name);
  const tasks = tables.filter((table: any) => table.id.includes('workitem') || table.id.includes('worksheet'))
    .flatMap((table: any) => table.initialRows || []);
  const groups = new Map<string, any[]>();
  let work = config.label;
  tasks.forEach((row: any) => {
    work = row.work || row.workName || work;
    if (!groups.has(work)) groups.set(work, []);
    groups.get(work)!.push(row);
  });
  if (!groups.size && measurementRows.length) groups.set(config.label, []);
  const toRow = (row: any, name: string): LayoutRow => ({ name, measurement: row.measurement || '', quantity: row.quantity ?? '', uom: row.uom || '' });
  return Array.from(groups, ([name, rows]) => ({
    name,
    tables: {
      Measurement: measurementRows.map((row: any) => toRow(row, row.name)),
      Service: rows.filter(row => row.task || row.taskName).map(row => toRow(row, row.task || row.taskName)),
      'Item Set': rows.filter(row => row.itemSpec || row.itemSetName).map(row => toRow(row, row.itemSpec || row.itemSetName)),
    },
  }));
};

export const ESTIMATION_LAYOUT_MODELS: LayoutModel[] = sectionModels.map(model => {
  const portions = model.section_type === 'apartment' ? apartmentPortions : model.section_type === 'floor-structure' ? floorStructurePortions : [];
  const services = model.section_type === 'apartment' ? apartmentServices : model.section_type === 'floor-structure' ? floorStructureServices : [];
  const itemSets = model.section_type === 'apartment' ? apartmentItemSets : model.section_type === 'floor-structure' ? floorStructureItemSets : [];
  return {
    ...model,
    procedures: procedureNames[model.section_type] ? procedureNames[model.section_type].map(name => ({
      name,
      // Section Model 7 uses the same initial rows for each procedure in a section.
      // Each procedure owns its copy so its tables can be edited independently.
      tables: {
      Measurement: portions.map(row => ({ name: row.portionName, measurement: row.measurement, quantity: row.quantity, uom: row.uom })),
      Service: services.map((row, index) => ({ name: row.serviceName, measurement: row.measurement, quantity: row.quantity, uom: row.uom, sequence: index + 1 })),
      'Item Set': itemSets.map(row => ({ name: row.itemSetName, itemSetType: row.itemSetType, measurement: row.measurement, quantity: row.quantity, uom: row.uom })),
      },
    })) : templateProcedures(model.section_type),
  };
});

