export const findPortion = (key?: string): PortionItem => {
  const portions = PORTION_GROUPS.reduce((all: PortionItem[], group: PortionGroup) => all.concat(group.items), []);
  return portions.find((portion: PortionItem) => portion.key === key) || PORTION_GROUPS[0].items[0];
};
