import { createSlice } from '@reduxjs/toolkit';
import { DEFAULT_UNIT_SYSTEM, loadProjectUnitSystem, saveProjectUnitSystem, } from '../util/measurementUnits';
// Define the initial state using that type
const initialState = {
    selectedProject: null,
    selectedBlock: null,
    unitSystem: DEFAULT_UNIT_SYSTEM,
};
export const slice = createSlice({
    name: 'commonData',
    initialState,
    reducers: {
        setSelectedProjectReducer: (state, action) => {
            state.selectedProject = action.payload;
            state.unitSystem = loadProjectUnitSystem(action.payload);
        },
        setSelectedBlockReducer: (state, action) => {
            state.selectedBlock = action.payload;
        },
        setUnitSystemReducer: (state, action) => {
            state.unitSystem = action.payload;
            saveProjectUnitSystem(state.selectedProject, action.payload);
        },
    },
});
export const { setSelectedProjectReducer, setSelectedBlockReducer, setUnitSystemReducer, } = slice.actions;
// Selectors
export const selectSelectedProject = (state) => state.common.selectedProject;
export const selectSelectedBlock = (state) => state.common.selectedBlock;
export const selectUnitSystem = (state) => state.common.unitSystem || DEFAULT_UNIT_SYSTEM;
export default slice.reducer;
